const DEFAULTS = { backendUrl: "http://localhost:3000", autoAnalyze: true, stripEmail: false, stripPhone: false, stripGuestName: false, debounceMs: 1500 };
chrome.runtime.onInstalled.addListener(async () => { const s = await chrome.storage.local.get(DEFAULTS); await chrome.storage.local.set({ ...DEFAULTS, ...s }); });
chrome.runtime.onMessage.addListener((msg, _sender, send) => { (async () => { try { const cfg = await chrome.storage.local.get(DEFAULTS); if (msg.type === "settings:get") return send({ ok: true, settings: cfg }); if (msg.type === "settings:set") { await chrome.storage.local.set(msg.settings || {}); return send({ ok: true }); } if (msg.type === "backend") { const url = String(cfg.backendUrl || DEFAULTS.backendUrl).replace(/\/$/, "") + msg.path; const r = await fetch(url, { method: msg.method || "GET", headers: { "content-type": "application/json", ...(msg.email ? { "x-nexus-user": msg.email } : {}) }, body: msg.body ? JSON.stringify(msg.body) : undefined, cache: "no-store" }); let data; try { data = await r.json(); } catch { data = { error: await r.text() }; } return send({ ok: r.ok, status: r.status, data }); } send({ ok: false, error: "Unknown message" }); } catch (e) { send({ ok: false, error: e instanceof Error ? e.message : String(e) }); } })(); return true; });
